module.exports.scale = 3;

module.exports.times = function (n) {
  return this.scale * n;
};

exports.twice = function (n) {
  return this.times(n) * 2;
};

exports.sum = function () {
  var total = this.scale;
  for (var i = 0; i < arguments.length; i++) {
    total += arguments[i];
  }
  return total;
};

exports.each = function (list, fn) {
  var out = [];
  for (var i = 0; i < list.length; i++) {
    out.push(fn(list[i]) + this.scale);
  }
  return out;
};

exports.run = function () {
  var k = 2;
  var parts = [];
  parts.push(module.exports.times(4));
  parts.push(exports.twice(5));
  parts.push(exports.sum(1, 2, 3));
  parts.push(
    exports
      .each([1, 2], function (x) {
        return x * k;
      })
      .join('+')
  );
  // Another receiver: the function reads what that receiver holds.
  var other = { scale: 10 };
  parts.push(exports.times.call(other, 2));
  var detached = exports.times;
  parts.push(String(detached(1)));
  return parts.join(' ');
};
